# Solve Social Golfers 8-4-6 using z3 or pysat
# 32 golfers, 8 groups of 4, 6 weeks
# Use pysat with cardinality constraints

from pysat.card import CardEnc, EncType
from pysat.formula import CNF, IDPool
from pysat.solvers import Glucose4

G = 8  # groups
S = 4  # group size
W = 6  # weeks
N = G * S  # 32 golfers

vpool = IDPool()
def x(w, p, g):
    return vpool.id(('x', w, p, g))

cnf = CNF()

# Each player in exactly one group per week
for w in range(W):
    for p in range(N):
        lits = [x(w,p,g) for g in range(G)]
        # exactly one
        cnf.append(lits)
        for i in range(len(lits)):
            for j in range(i+1,len(lits)):
                cnf.append([-lits[i],-lits[j]])

# Each group has exactly S players per week
for w in range(W):
    for g in range(G):
        lits = [x(w,p,g) for p in range(N)]
        cl = CardEnc.equals(lits=lits, bound=S, vpool=vpool, encoding=EncType.seqcounter)
        cnf.extend(cl.clauses)

# For each pair, at most one week together
# m[w,p,q] true iff p and q in same group week w
# m = AND over g: (x[w,p,g] <-> x[w,q,g])... simpler: define meet var
def meet(w,p,q):
    return vpool.id(('m',w,p,q))

for w in range(W):
    for p in range(N):
        for q in range(p+1,N):
            mv = meet(w,p,q)
            # mv <-> exists g: x[w,p,g] & x[w,q,g]
            # For each g: x[w,p,g] & x[w,q,g] -> mv
            for g in range(G):
                cnf.append([-x(w,p,g), -x(w,q,g), mv])
            # mv -> exists g: both. That is mv -> OR_g (x[w,p,g] & x[w,q,g])
            # Since each is in exactly one group, mv -> for each g, x[w,p,g] <-> x[w,q,g]
            # Equivalently: mv -> (x[w,p,g] -> x[w,q,g]) for all g
            for g in range(G):
                cnf.append([-mv, -x(w,p,g), x(w,q,g)])
                cnf.append([-mv, x(w,p,g), -x(w,q,g)])

# At most one week: for each pair, sum_w meet(w,p,q) <= 1
for p in range(N):
    for q in range(p+1,N):
        lits = [meet(w,p,q) for w in range(W)]
        cl = CardEnc.atmost(lits=lits, bound=1, vpool=vpool, encoding=EncType.seqcounter)
        cnf.extend(cl.clauses)

# Symmetry breaking: week 0 fixed
for p in range(N):
    g = p // S
    cnf.append([x(0, p, g)])

# Symmetry breaking: player 0 in group 0 every week
for w in range(W):
    cnf.append([x(w, 0, 0)])

print("clauses:", len(cnf.clauses), "vars:", vpool.top)

solver = Glucose4()
solver.append_formula(cnf.clauses)
print("solving...")
res = solver.solve()
print("result:", res)

if res:
    model = set(solver.get_model())
    schedule = [0]*(W*N)
    for w in range(W):
        for p in range(N):
            for g in range(G):
                if x(w,p,g) in model:
                    schedule[w*N + p] = g
                    break
    # Verify
    for w in range(W):
        groups = [[] for _ in range(G)]
        for p in range(N):
            groups[schedule[w*N+p]].append(p)
        assert all(len(gr)==4 for gr in groups), groups
    pair_weeks = {}
    for w in range(W):
        groups = [[] for _ in range(G)]
        for p in range(N):
            groups[schedule[w*N+p]].append(p)
        for gr in groups:
            for i in range(len(gr)):
                for j in range(i+1,len(gr)):
                    pr = (gr[i],gr[j])
                    pair_weeks.setdefault(pr,[]).append(w)
    bad = [(pr,ws) for pr,ws in pair_weeks.items() if len(ws)>1]
    print("bad pairs:", bad[:5])
    print(schedule)
